<script lang="ts">
 import {invoke} from '@tauri-apps/api/core';
 type Dataset={latitude:number,longitude:number,timezone:string,hourly:Record<string,(number|string|null)[]>,hourly_units:Record<string,string>};
 type Forecast={weather:Dataset|null,marine:Dataset|null,retrieved_at:string};
 let latitude='',longitude='',loading=false,error='',fromCache=false; let result:Forecast|null=null;
 async function fetchForecast(){
  const lat=Number(latitude),lon=Number(longitude);
  if(!latitude.trim()||!longitude.trim()||!Number.isFinite(lat)||!Number.isFinite(lon)||lat < -90||lat > 90||lon < -180||lon > 180){error='Inserisci latitudine e longitudine valide.';return}
  error='';loading=true;
  try{result=await invoke('fetch_forecast',{latitude:lat,longitude:lon});fromCache=false}catch(e){error=typeof e==='object'&&e!==null&&'message' in e?String(e.message):'Impossibile ottenere le previsioni.'}finally{loading=false}
 }
 async function loadCached(){ if(!latitude.trim()||!longitude.trim()){error='Inserisci le coordinate.';return} try{result=await invoke('cached_forecast',{latitude:Number(latitude),longitude:Number(longitude)});fromCache=true;error=result?'':'Nessuna previsione salvata per queste coordinate.'}catch{error='Impossibile leggere la cache.'} }
 const label:Record<string,string>={temperature_2m:'Temperatura',precipitation:'Precipitazione',wind_speed_10m:'Vento',wind_direction_10m:'Direzione vento',wind_gusts_10m:'Raffiche',wave_height:'Altezza significativa onde',wave_direction:'Direzione onde',wave_period:'Periodo onde',sea_surface_temperature:'Temperatura superficie mare'};
</script>
<div class="weather"><h2>Meteo e mare</h2><p>Le coordinate vengono inviate a Open-Meteo quando richiedi le previsioni. Il dato descrive una cella del modello, non le condizioni esatte sulla riva.</p><form on:submit|preventDefault={fetchForecast}><label>Latitudine<input type="number" step="any" min="-90" max="90" bind:value={latitude} required></label><label>Longitudine<input type="number" step="any" min="-180" max="180" bind:value={longitude} required></label><button class="primary" disabled={loading}>{loading?'Caricamento…':'Recupera previsioni'}</button><button type="button" on:click={loadCached}>Leggi ultima previsione salvata</button></form>{#if error}<p class="error" role="alert">{error}</p>{/if}
{#if result}<p class="source">Recuperate il {new Intl.DateTimeFormat('it-IT',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Rome'}).format(new Date(Number(result.retrieved_at)*1000))}. Fuso Europe/Rome. Fonte: Open-Meteo e fornitori dei modelli; verifica i dettagli sul servizio. {fromCache ? 'Previsione salvata in precedenza: può essere superata.' : 'La risposta è salvata localmente.'}</p>{#each [{name:'Meteo',data:result.weather},{name:'Mare',data:result.marine}] as section}<h3>{section.name}</h3>{#if section.data}<p class="source">Cella modello: {section.data.latitude}, {section.data.longitude}. Valori orari fino a {section.data.hourly.time?.at(-1) || 'data non disponibile'}.</p><div class="weather-table"><table><thead><tr><th>Ora</th>{#each Object.keys(section.data.hourly).filter(k=>k!=='time') as key}<th>{label[key] || key} ({section.data.hourly_units[key]})</th>{/each}</tr></thead><tbody>{#each section.data.hourly.time.slice(0,24) as time,index}<tr><td>{time}</td>{#each Object.keys(section.data.hourly).filter(k=>k!=='time') as key}<td>{section.data.hourly[key]?.[index] ?? '—'}</td>{/each}</tr>{/each}</tbody></table></div>{:else}<p class="source">Dati non disponibili per questa richiesta.</p>{/if}{/each}<p class="source">Mostrate le prime 24 ore. Nessun valore oltre l’orizzonte ricevuto è una previsione. <a href="https://open-meteo.com/en/docs/marine-weather-api">Attribuzioni dei modelli marini</a>.</p>{/if}</div>
